const set = globalThis.setTimeout;
const cancel = globalThis.clearTimeout;
const selected = new Map();
const start = performance.now();
let armed = false;
let index = 0;
function log(s) { console.log('[lifelines-clock]', Math.round(performance.now() - start), s); }
globalThis.setTimeout = function(callback, ms, ...args) {
  const trace = new Error().stack;
  const kind = ((ms === 180 && trace.includes('settleRender')) || (ms === 20 && trace.includes('requiredElementEventually'))) ? 'fixture' : ms === 150 && trace.includes('setContent') ? 'panel' : '';
  if (!kind) return set(callback, ms, ...args);
  const number = ++index;
  log('schedule '+kind+' '+number+' '+ms);
  const id = set((...args) => { log('fire '+kind+' '+number); callback(...args); }, ms, ...args);
  selected.set(id, number);
  if (kind === 'fixture' && !armed && process.env.LIFELINE_STALL_MS) {
    armed = true;
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,Number(process.env.LIFELINE_STALL_MS));
  }
  return id;
};
globalThis.clearTimeout = function(id) {
 if(selected.has(id)) log('cancel '+selected.get(id));
 return cancel(id);
};

